// Browser-side anonymization - TypeScript port of pipeline/anonymize.py (same rules, same tokens).
// Runs on the lawyer's computer: the PDF and the personal data never leave the browser;
// only the anonymized text (after the lawyer's approval) is sent to the API.
// Parity with Python is checked by shared/anonymize.test.ts on texts generated by scripts/export_schemas.py.

// --- helpers: Unicode-aware word boundaries and case-insensitive fragments -------------------

const W = "[\\p{L}\\p{N}_]"; // Python's Unicode \w
const B_START = `(?<!${W})`;
const B_END = `(?!${W})`;

/** Case-insensitive literal fragment without a global `i` flag: "abc" -> "[aA][bB][cC]". */
function ci(word: string): string {
  return [...word].map((ch) => {
    const lo = ch.toLowerCase();
    const up = ch.toUpperCase();
    return lo === up ? ch.replace(/[.*+?^${}()|[\]\\]/g, "\\$&") : `[${lo}${up}]`;
  }).join("");
}

// --- checksums ------------------------------------------------------------------------------

export function validPesel(s: string): boolean {
  if (!/^\d{11}$/.test(s)) return false;
  const w = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3];
  const sum = w.reduce((acc, k, i) => acc + Number(s[i]) * k, 0);
  return (10 - (sum % 10)) % 10 === Number(s[10]);
}

export function validNip(s: string): boolean {
  const d = s.replace(/\D/g, "");
  if (d.length !== 10) return false;
  const w = [6, 5, 7, 2, 3, 4, 5, 6, 7];
  const c = w.reduce((acc, k, i) => acc + Number(d[i]) * k, 0) % 11;
  return c !== 10 && c === Number(d[9]);
}

export function validRegon(s: string): boolean {
  const d = s.replace(/\D/g, "");
  let w: number[];
  if (d.length === 9) w = [8, 9, 2, 3, 4, 5, 6, 7];
  else if (d.length === 14) w = [2, 4, 8, 5, 0, 9, 7, 3, 6, 1, 2, 4, 8];
  else return false;
  return (w.reduce((acc, k, i) => acc + Number(d[i]) * k, 0) % 11) % 10 === Number(d[d.length - 1]);
}

export function validIdCard(s: string): boolean {
  s = s.replace(/ /g, "").toUpperCase();
  if (!/^[A-Z]{3}\d{6}$/.test(s)) return false;
  const values = [...s.slice(0, 3)].map((c) => c.charCodeAt(0) - 55).concat([...s.slice(3)].map(Number));
  const w = [7, 3, 1, 0, 7, 3, 1, 7, 3];
  return values.reduce((acc, v, i) => acc + v * w[i], 0) % 10 === values[3];
}

const KW_CHARS = "0123456789XABCDEFGHIJKLMNOPRSTUWYZ";

export function validKw(s: string): boolean {
  const m = /^([A-Z]{2}\d[A-Z])\/(\d{8})\/(\d)$/.exec(s.toUpperCase());
  if (!m) return false;
  const chars = m[1] + m[2];
  const w = [1, 3, 7, 1, 3, 7, 1, 3, 7, 1, 3, 7];
  const total = [...chars].reduce((acc, c, i) => acc + KW_CHARS.indexOf(c) * w[i], 0);
  return total % 10 === Number(m[3]);
}

export function validIbanPl(s: string): boolean {
  let d = s.replace(/\s/g, "").toUpperCase();
  if (d.startsWith("PL")) d = d.slice(2);
  if (!/^\d{26}$/.test(d)) return false;
  return BigInt(d.slice(2) + "2521" + d.slice(0, 2)) % 97n === 1n;
}

// --- rules ------------------------------------------------------------------------------------

interface Rule { label: string; pattern: RegExp; check?: (s: string) => boolean; group?: number }

const NAME_CHARS_UP = "A-ZŁŚŻŹĆŃÓ";
const NAME_CHARS_LO = "a-ząćęłńóśźż";
const NAME = `[${NAME_CHARS_UP}][${NAME_CHARS_LO}]+(?:-[${NAME_CHARS_UP}][${NAME_CHARS_LO}]+)?`;

const RULES: Rule[] = [
  // Also as OCR reads it: "jan. kowalskiQexample.com", "jan ©example.pl", "jan(at)example.pl".
  { label: "EMAIL", pattern: /[\p{L}\p{N}_.+-]+(?:(?<=\.)\s[\p{L}\p{N}_.+-]+)?\s?(?:@|©|\(at\)|Q(?=[a-z0-9-]+(?:\.[a-z0-9-]+)*\.[a-z]{2,}(?![\p{L}\p{N}_])))\s?[\p{L}\p{N}_-]+(?:\.[\p{L}\p{N}_-]+)+/gu },
  { label: "KONTO", pattern: new RegExp(`(?<!${W})(?:PL\\s?)?\\d{2}(?:[ ]?\\d{4}){6}(?!\\d)`, "gu"), check: validIbanPl },
  { label: "KONTO", pattern: new RegExp(`(?:rachun${W}*|konto|konta|nr\\s+rach\\.?)[^\\d]{0,40}((?:PL\\s?)?\\d{2}(?:[ ]?\\d{4}){6})`, "giu"), group: 1 },
  { label: "KW", pattern: new RegExp(`${B_START}[A-Z]{2}\\d[A-Z]\\/\\d{8}\\/\\d${B_END}`, "gu") },
  { label: "PESEL", pattern: /(?<!\d)\d{11}(?!\d)/gu, check: validPesel },
  { label: "PESEL", pattern: /PESEL[:\s]*(?:nr\s*)?([\dOoIl]{11})(?![\dOoIl])/giu, group: 1 },
  { label: "NIP", pattern: /NIP[:\s]*((?:PL)?\d{3}-?\d{3}-?\d{2}-?\d{2}|\d{3}-\d{2}-\d{2}-\d{3})/giu, group: 1 },
  { label: "NIP", pattern: /(?<![\d-])\d{3}-\d{3}-\d{2}-\d{2}(?![\d-])/gu, check: validNip },
  { label: "REGON", pattern: /REGON[:\s]*(\d{9}(?:\d{5})?)/giu, group: 1 },
  { label: "DOWOD", pattern: new RegExp(`${B_START}[A-Z]{3}\\s?\\d{6}${B_END}`, "gu"), check: validIdCard },
  // "dowodem osobistym serii i nr: ABC 123456", "paszportem nr FA1234567"
  { label: "DOWOD", pattern: new RegExp(`(?:${ci("dow")}${W}*\\s+${ci("osobist")}${W}*|${ci("paszport")}${W}*)[^\\n\\d]{0,40}?(?<![A-Za-z])([A-Z][A-Z0-9]{1,3}\\s?[0-9OoIl]{5,7})(?![A-Za-z0-9])`, "gu"), group: 1 },
  // Date of birth: "urodzony dnia 1 stycznia 1990 roku", "ur. 01.01.1990", "data urodzenia: 1990-01-01"
  { label: "URODZENIE", pattern: new RegExp(`${B_START}(?:urodzon${W}*|ur\\.|data\\s+urodzenia:?)\\s+(?:w\\s+dniu\\s+|dnia\\s+)?(\\d{1,2}[.\\s/-]+(?:\\d{1,2}|[a-ząćęłńóśźż]{4,})[.\\s/-]+\\d{4}|\\d{4}-\\d{2}-\\d{2})`, "giu"), group: 1 },
  // Maiden / previous surname: "z domu Kowalska", "nazwisko rodowe: Kowalska", "primo voto Nowak"
  { label: "NAZWISKO", pattern: new RegExp(`${B_START}(?:${ci("z")}\\s+${ci("domu")}|${ci("nazwisk")}${W}*\\s+${ci("rodow")}${W}*:?|${ci("primo")}\\s+${ci("voto")}|${ci("secundo")}\\s+${ci("voto")})\\s+([${NAME_CHARS_UP}][${NAME_CHARS_LO}]+(?:\\s?[-–]\\s?[${NAME_CHARS_UP}][${NAME_CHARS_LO}]+)?)`, "gu"), group: 1 },
  { label: "RODZICE", pattern: new RegExp(`(?:${ci("imiona")}\\s+${ci("rodzic")}${W}*|${ci("imię")}\\s+${ci("ojca")}\\s+[iI]\\s+${ci("matki")})[:\\s]+([${NAME_CHARS_UP}][${NAME_CHARS_LO}]+(?:\\s*(?:[iI]|,)\\s*[${NAME_CHARS_UP}][${NAME_CHARS_LO}]+)*)`, "gu"), group: 1 },
  // "syn Romana i Teresy", "córka Pawła"
  { label: "RODZICE", pattern: new RegExp(`${B_START}(?:syn|córka)\\s+([${NAME_CHARS_UP}][${NAME_CHARS_LO}]+(?:\\s+i\\s+[${NAME_CHARS_UP}][${NAME_CHARS_LO}]+)?)`, "gu"), group: 1 },
  { label: "TELEFON", pattern: /(?<![\d/])(?:\+48[\s-]?)?\d{3}[\s-]\d{3}[\s-]\d{3}(?![\d/])/gu },
  { label: "TELEFON", pattern: /(?<![\d/])\+48\s?\d{9}(?!\d)/gu },
  // Landline: "(22) 123 45 67", "22 123-45-67"
  { label: "TELEFON", pattern: /(?<![\d/])(?:\+48[\s-]?)?\(?\d{2}\)?[\s-]\d{3}[\s-]\d{2}[\s-]\d{2}(?![\d/])/gu },
  { label: "TELEFON", pattern: /(?:tel\.?|telefon[\p{L}\p{N}_]*)[:\s]*(\+?\(?\d[\d\s()-]{7,16}\d)/giu, group: 1 },
  { label: "KOD", pattern: /(?<![\d-])\d{2}-\d{3}(?![\d-])/gu },
];

const ADDRESS = new RegExp(
  `${B_START}(?:ul\\.|ulicy|ulica|al\\.|alei|aleja|pl\\.|placu|plac|os\\.|osiedle|osiedlu)\\s+` +
  `(?:[A-ZŁŚŻŹĆŃÓĘĄ0-9][\\p{L}\\p{N}_.\\-]*\\s+){1,4}?\\d+[A-Za-z]?(?:\\s?\\/\\s?\\d+[A-Za-z]?|\\s+(?:lok\\.|m\\.)\\s*\\d+)?`,
  "gu",
);

// A name word; double surnames with a hyphen or a spaced dash, also broken at the line end ("Nowak-\nKowalska").
const WORD = `[${NAME_CHARS_UP}][${NAME_CHARS_LO}]+`;
const NAME_X = `${WORD}(?:(?:[ ]?[-–][ ]?|-\\n)${WORD})?`;
const CAPS = "[A-ZŁŚŻŹĆŃÓĘĄ]{2,}(?:-[A-ZŁŚŻŹĆŃÓĘĄ]{2,})?"; // names written in capitals ("JAN KOWALSKI")
const ANY = `(?:${NAME_X}|${CAPS})`;
// Surname with a particle: "van der Berg", "de Gaulle", "von Braun".
const LAST = `(?:(?:van|von|de|der|den|del|da|di|du|dos|la|le)\\s+){0,2}${NAME_X}`;
const TITLES = "(?:\\s+(?:dr|hab|prof|mgr|mec)\\.){0,3}";
const TITLES_CI = `(?:\\s+(?:${ci("dr")}|${ci("hab")}|${ci("prof")}|${ci("mgr")}|${ci("mec")})\\.){0,3}`;
const PERSON = new RegExp(`${B_START}(?:Pan|Pani|Panem|Panią|Pana|Panu|p\\.)${TITLES}\\s+(${NAME_X})\\s+(${LAST})(?:[ \\t]+(${LAST})(?=\\s*,))?`, "gu");
const ROLE_WITH_SEPARATOR = `(?:${ci("nabywc")}${W}*|${ci("nabywczyni")}${W}*|${ci("kupując")}${W}*|${ci("sprzedając")}${W}*|` +
  `${ci("przedstawiciel")}${W}*(?:\\s+${ci("dewelopera")})?|${ci("pełnomocni")}${W}*(?:\\s+[A-ZŁŚŻ]{2,})?|` +
  `${ci("stawając")}${W}*|${ci("wnioskodawc")}${W}*|${ci("uczestni")}${W}*|${ci("świadek")}|${ci("kancelaria")}\\s+${ci("notarialna")}|` +
  `${ci("imię")}\\s+${ci("i")}\\s+${ci("nazwisko")}(?:\\s+${W}+)?|${ci("odbierając")}${W}*|${ci("przekazując")}${W}*)`;
const ROLE_FREE = `(?:${ci("notariusz")}${W}*(?:\\s+${ci("w")}\\s+[${NAME_CHARS_UP}]${W}+)?${TITLES_CI}|${ci("zastępc")}${W}*\\s+${ci("notarialn")}${W}*|${ci("reprezentowan")}${W}*\\s+${ci("przez")})`;
const PERSON_BY_ROLE = new RegExp(`(?:${ROLE_WITH_SEPARATOR}\\s*[:—–-]\\s*|${ROLE_FREE}\\s+)(${ANY})\\s+(${LAST}|${CAPS})(?:[ \\t]+(${LAST}|${CAPS}))?`, "gu");
// Two first names, as notaries write them: "Adam Michał Nowak, używający (pierwszego) imienia Adam".
const PERSON_TWO_NAMES = new RegExp(`(${NAME_X})\\s+(${NAME_X})\\s+(${LAST}),?\\s+${ci("używając")}${W}*\\s+(?:${ci("pierwszego")}\\s+)?${ci("imienia")}${B_END}`, "gu");
const PERSON_BEFORE_ID = new RegExp(
  `(${NAME_X})\\s+(${LAST}),?\\s+(?:\\(?\\s*)?(?:PESEL|${ci("legitymując")}${W}*|${ci("zamieszkał")}${W}*|${ci("córk")}${W}*|${ci("syn")}${B_END}|` +
  `${ci("według")}\\s+${ci("oświadcz")}${W}*|${ci("wg")}\\.?\\s+${ci("ośw")}${W}*|${ci("imiona")}\\s+${ci("rodzic")}${W}*|${ci("imię")}\\s+${ci("ojca")}|` +
  `${ci("obywatel")}${W}*|${ci("urodzon")}${W}*|${ci("działając")}${W}*|${ci("używając")}${W}*|${ci("z")}\\s+${ci("domu")}|${ci("dow")}${W}*\\s+${ci("osobist")}${W}*)`,
  "gu",
);
// Name before the notary's title: "przede mną Katarzyną Nowak, notariuszem", "Jana Nowaka, zastępcę notarialnego".
const PERSON_BEFORE_NOTARY = new RegExp(
  `(${NAME_X})[ \\t]+(${LAST})(?:[ \\t]+(${LAST}))?,?\\s+(?:${ci("notariusz")}${W}*|${ci("zastępc")}${W}*\\s+${ci("notarialn")}${W}*|${ci("asesor")}${W}*\\s+${ci("notarialn")}${W}*)`,
  "gu",
);
// Two persons at once: "Nabywcą: Jan Nowak i Anna Nowak", "notariuszem Janem Nowakiem/Anną Kowalską".
const PERSON_PAIR = new RegExp(
  `(?:${ROLE_WITH_SEPARATOR}\\s*[:—–-]\\s*|${ROLE_FREE}\\s+|${B_START}(?:Państwo|Państwa|małżonkowie|małżonków)\\s+)` +
  `(${NAME_X})\\s+(${LAST})\\s*(?:\\s(?:i|oraz)\\s|\\/)\\s*(${NAME_X})\\s+(${LAST})`,
  "gud",
);
// Spouses with a shared surname: "Państwo Jan i Anna Nowakowie".
const PERSON_SHARED = new RegExp(`${B_START}(?:Państwo|Państwa|małżonkowie|małżonków)\\s+(${NAME_X})\\s+i\\s+(${NAME_X})\\s+(${LAST})`, "gud");
// Safety net in the komparycja: a numbered entry starting with a name ("1. Jan Nowak,", "2/ Anna Maria Kowalska –").
const PERSON_ENTRY = new RegExp(
  `^[ \\t]*(?:\\d{1,2}[ \\t]?[.)/]|ad[ \\t]?\\d{1,2}[.)]?)[ \\t]*(?:(?:Pan|Pani)${TITLES}[ \\t]+)?` +
  `(${ANY})[ \\t]+(${LAST}|${CAPS})(?:[ \\t]+(${LAST}|${CAPS}))?(?=[ \\t]*[,(]|[ \\t]+[-–][ \\t])`,
  "gmu",
);
const KOMPARYCJA_START = new RegExp(`${ci("stawi")}${W}*\\s+${ci("si")}[ęeĘE]`, "u");
const KOMPARYCJA_END = new RegExp(
  `${ci("umowa")}\\s+${ci("deweloperska")}|${ci("umowa")}\\s+${ci("sprzeda")}|§\\s*1(?!\\d)|${ci("tożsamość")}\\s+${ci("stawając")}`, "gu");
const KOMPARYCJA_MAX = 6000;
// Words replaced in the text once a person is known (single words; capitals too: "KOWALSKI").
const PERSON_WORD = new RegExp(`${B_START}(?:${WORD}|[A-ZŁŚŻŹĆŃÓĘĄ]{2,})${B_END}`, "gu");

const STOP = new Set(["Spółka", "Spółki", "Deweloper", "Dewelopera", "Nabywca", "Nabywcy", "Kupujący", "Sprzedający",
  "Notariusz", "Rzeczypospolitej", "Polskiej", "Warszawa", "Warszawie", "Sądu", "Rejonowego",
  "Imiona", "Dowód", "Adres", "Lokalu", "Lokal", "Krajowego", "Ośrodka", "Skarbu", "Państwa"]);

const TERM_PREFIXES = ["całkowit", "przenosząc", "budynk", "budynek", "nieruchomoś", "harmonogram", "rachun", "dewelop",
  "nabywc", "inwestycj", "dokumentacj", "odbior", "odbiór", "wydani", "protok", "opłat", "komórk",
  "lokatorsk", "garaż", "wspóln", "zadani", "przedsięwzię", "prospekt", "załącznik", "regulamin",
  "rozporządzeni", "kodeks", "notarialn", "repertorium", "spółk", "pozwoleni", "postojow", "mieszkaln",
  "tożsamoś", "stawając", "zastrzeż", "numer", "rejestr", "komplementariusz", "komandyt", "ewidencj",
  "informacj", "centraln"];
const TERM_STEMS = new Set(["cen", "kar", "stron", "sąd", "umow", "lokal", "termin", "aneks", "miejsc", "artykuł",
  "ustaw", "decyzj", "warunk", "zarząd"]);

const SUFFIXES = ["iego", "iemu", "ymi", "imi", "ich", "ych", "ego", "emu", "owi", "iej", "ach", "ami", "ów",
  "ej", "ym", "im", "em", "ie", "om", "ą", "ę", "y", "i", "a", "e", "u", "o"]
  .map((s, i) => ({ s, i })).sort((a, b) => b.s.length - a.s.length || a.i - b.i).map((x) => x.s);

export function stem(word: string): string {
  const w = word.toLowerCase();
  for (const suffix of SUFFIXES) {
    if (w.endsWith(suffix) && [...w].length - [...suffix].length >= 3) return w.slice(0, w.length - suffix.length);
  }
  return w;
}

function isTerm(word: string): boolean {
  const w = word.toLowerCase();
  return STOP.has(word) || TERM_STEMS.has(stem(word)) || TERM_PREFIXES.some((t) => w.startsWith(t));
}

// Role given after the person's entry in the komparycja: "..., zwani dalej „Nabywcą”",
// "Natalia Nowak zwana będzie również jako „Nabywca”", "Adam Nowak również jako „Przedstawiciel Dewelopera”".
const ROLE_FILL = `(?:${ci("dalej")}|${ci("łącznie")}|${ci("także")}|${ci("również")}|${ci("każdy")}\\s+${ci("z")}\\s+${ci("osobna")}|` +
  `${ci("będzie")}|${ci("będą")}|${ci("jest")}|${ci("są")}|` +
  `${ci("w")}\\s+(?:${ci("dalszej")}\\s+${ci("treści")}(?:\\s+${ci("niniejszego")})?\\s+(?:${ci("aktu")}|${ci("umowy")})|${ci("niniejszej")}\\s+${ci("umowie")}|${ci("niniejszym")}\\s+${ci("akcie")}))`;
const ROLE_AFTER = new RegExp(
  `(?:(?:${ci("zwan")}|${ci("nazywan")}|${ci("określan")})${W}*(?:\\/${W}+)?\\s+(?:${ROLE_FILL}:?\\s+)*(?:${ci("jako")}\\s+)?|(?:${ROLE_FILL}\\s+)*${ci("jako")}\\s+(?=[„"”']))` +
  `[„"”']?\\s*(?:${ci("spółk")}${W}*[”"]?\\s+${ci("lub")}\\s+[„"]?)?` +
  `((?:${ci("nabywc")}|${ci("kupując")}|${ci("sprzedając")}|${ci("dewelop")}|${ci("przedstawiciel")}|${ci("pełnomocni")})${W}*)`,
  "gu",
);
const NAME_BEFORE_MARKER = new RegExp(`(${NAME_X})\\s+(${LAST})[\\s,]*$`, "u");
const ROLE_AFTER_NAMES: [string, string[]][] = [
  ["buyer", ["nabywc", "kupując"]], ["seller", ["sprzedając"]], ["representative", ["dewelop", "przedstawiciel", "pełnomocni"]],
];
const ROLE_AFTER_REACH = 1500; // characters before the marker that may belong to the same komparycja entry

function roleAfter(word: string): string | null {
  const w = word.toLowerCase();
  return ROLE_AFTER_NAMES.find(([, prefixes]) => prefixes.some((p) => w.startsWith(p)))?.[0] ?? null;
}

const ROLE_NAMES: [string, string[]][] = [
  ["buyer", ["nabywc", "nabywczyni", "kupując", "odbierając"]],
  ["seller", ["sprzedając"]],
  ["representative", ["przedstawiciel", "pełnomocni", "reprezentowan", "przekazując"]],
  ["notary", ["notariusz", "zastępc", "kancelaria", "asesor"]],
];

/** Span of the komparycja: from "stawili się" to the start of the agreement (or a fixed length). */
function komparycja(text: string): [number, number] {
  const start = KOMPARYCJA_START.exec(text);
  if (!start) return [0, 0];
  KOMPARYCJA_END.lastIndex = start.index + start[0].length;
  const end = KOMPARYCJA_END.exec(text);
  return [start.index, Math.min(end ? end.index : text.length, start.index + KOMPARYCJA_MAX)];
}

const isUpperChar = (ch: string) => ch !== ch.toLowerCase() && ch === ch.toUpperCase();

/** Capitalized parts of a name: "van der Berg" -> [Berg], "Nowak – Kowalska" -> [Nowak, Kowalska]. */
function parts(name: string): string[] {
  return name.split(/[\s\-–]+/u).filter((p) => p && isUpperChar(p[0]));
}

/** Name for the UI and letters: one line, "JAN KOWALSKI" -> "Jan Kowalski". */
function display(name: string): string {
  name = name.includes("-\n") ? name.replace(/\s*\n\s*/gu, "") : name.replace(/\s+/gu, " ");
  const withoutParticles = name.replace(new RegExp(`${B_START}(?:van|von|de|der|den|del|da|di|du|dos|la|le)${B_END}`, "gu"), "");
  if (/[a-ząćęłńóśźż]/u.test(withoutParticles)) return name;
  return name.replace(/[A-ZŁŚŻŹĆŃÓĘĄ]{2,}/gu, (w) => w[0] + w.slice(1).toLowerCase());
}

/** Drops trailing parts of a compound that are contract terms ("Nowak – Deweloper" -> "Nowak");
 *  null when the name itself is a term. */
function clean(word: string | undefined): string | null {
  if (!word) return null;
  const pieces = word.split(/(\s?[-–]\s?|-\n)/u);
  const head = parts(pieces[0]);
  if (!head.length || head.some(isTerm)) return null;
  let kept = pieces[0];
  for (let i = 1; i + 1 < pieces.length; i += 2) {
    if (isTerm(pieces[i + 1])) break;
    kept += pieces[i] + pieces[i + 1];
  }
  return kept;
}

const NOT_ABBREV = ["ul", "al", "pl", "os", "m", "lok", "nr"].map((a) => `(?<!(?<!${W})${a})`).join("");
const ADDRESS_LINE = new RegExp(
  `(?:adres${W}*\\s*:|zamieszkał${W}*|zam\\.)\\s*(?:w\\s+${W}+\\s*,?\\s*)?(?:przy\\s+)?` +
  `([^\\n]{5,140}?)(?:${NOT_ABBREV}\\.(?:\\s|$)|\\n|$)`,
  "iu",
);

function roleOf(matched: string): string | null {
  const head = matched.toLowerCase();
  for (const [role, prefixes] of ROLE_NAMES) {
    if (prefixes.some((p) => head.startsWith(p) || head.slice(0, 40).includes(` ${p}`))) return role;
  }
  return null;
}

function addressAfter(text: string, pos: number): string | null {
  let window = text.slice(pos, pos + 400);
  PERSON_BY_ROLE.lastIndex = 0;
  const next = new RegExp(PERSON_BY_ROLE.source, "u").exec(window);
  if (next) window = window.slice(0, next.index);
  const m = ADDRESS_LINE.exec(window);
  return m ? m[1].trim().replace(/[,;]+$/, "") : null;
}

// --- anonymizer -----------------------------------------------------------------------------

export interface Replacement { token: string; original: string; label: string }
export interface Person { token: string; name: string; role: string | null; address: string | null }

export class Anonymizer {
  mapping = new Map<string, string>(); // token -> original
  replacements: Replacement[] = [];
  persons = new Map<string, { name: string; role: string | null; address: string | null }>();
  private byOriginal = new Map<string, string>();
  private counters = new Map<string, number>();
  private personStems = new Map<string, string>();
  private personBases = new Map<string, string>();

  private key(label: string, original: string) { return `${label}\u0000${original}`; }

  private token(label: string, original: string): string {
    const key = this.key(label, original);
    if (!this.byOriginal.has(key)) {
      const n = (this.counters.get(label) ?? 0) + 1;
      this.counters.set(label, n);
      const token = `[${label}_${n}]`;
      this.byOriginal.set(key, token);
      this.mapping.set(token, original);
    }
    const token = this.byOriginal.get(key)!;
    this.replacements.push({ token, original, label });
    return token;
  }

  /** Names are collected from all documents first, then replaced everywhere. */
  learnNames(texts: Iterable<string>): void {
    for (const text of texts) {
      const found: [number, string][] = []; // (position, token) of persons in this text
      const add = (pos: number, end: number, first: string, second: string, third: string | undefined, role: string | null) => {
        const [firstC, secondC, thirdC] = [clean(first), clean(second), clean(third)];
        const [middle, last] = thirdC ? [secondC, thirdC] : [null, secondC];
        if (!firstC || !secondC || !last) return;
        const token = this.registerPerson(firstC, last, middle);
        const name = display(middle ? `${firstC} ${middle} ${last}` : `${firstC} ${last}`);
        this.notePerson(token, name, role, addressAfter(text, end));
        found.push([pos, token]);
      };
      const withThird = new Set([PERSON_TWO_NAMES, PERSON, PERSON_BY_ROLE, PERSON_BEFORE_NOTARY]);
      for (const regex of [PERSON_TWO_NAMES, PERSON, PERSON_BEFORE_ID, PERSON_BY_ROLE, PERSON_BEFORE_NOTARY]) {
        for (const m of text.matchAll(regex)) {
          const role = regex === PERSON_BY_ROLE ? roleOf(m[0]) : regex === PERSON_BEFORE_NOTARY ? "notary" : null;
          add(m.index!, m.index! + m[0].length, m[1], m[2], withThird.has(regex) ? m[3] : undefined, role);
        }
      }
      for (const m of text.matchAll(PERSON_PAIR)) {
        const role = roleOf(m[0]);
        const end = m.index! + m[0].length;
        add(m.index!, end, m[1], m[2], undefined, role);
        add(m.indices![3]![0], end, m[3], m[4], undefined, role);
      }
      for (const m of text.matchAll(PERSON_SHARED)) {
        const end = m.index! + m[0].length;
        add(m.index!, end, m[1], m[3], undefined, null);
        add(m.indices![2]![0], end, m[2], m[3], undefined, null);
      }
      const [start, stop] = komparycja(text);
      const region = text.slice(0, stop);
      PERSON_ENTRY.lastIndex = start; // like Python's finditer(text, start, end)
      for (let m = PERSON_ENTRY.exec(region); m; m = PERSON_ENTRY.exec(region)) {
        add(m.index, m.index + m[0].length, m[1], m[2], m[3], null);
        if (m[0].length === 0) PERSON_ENTRY.lastIndex += 1;
      }
      this.rolesAfter(text, found);
    }
  }

  /** Persons without a role get the one named after their entry ("zwani dalej Nabywcą"). */
  private rolesAfter(text: string, found: [number, string][]) {
    const markers = [...text.matchAll(ROLE_AFTER)].map((m) => ({ m, role: roleAfter(m[1]), targeted: false }));
    for (const marker of markers) { // "Natalia Nowak zwana będzie jako Nabywca": that person only
      const start = marker.m.index!;
      const named = NAME_BEFORE_MARKER.exec(text.slice(Math.max(0, start - 80), start));
      const token = named ? this.knownPerson(named[1], named[2]) : undefined;
      if (!token) continue;
      marker.targeted = true;
      const person = this.persons.get(token);
      if (marker.role && person && person.role === null) person.role = marker.role;
    }
    let boundary = 0;
    for (const { m, role, targeted } of markers) { // "..., PESEL ..., zwani dalej Nabywcą": entries since the previous marker
      if (!targeted) {
        const start = Math.max(boundary, m.index! - ROLE_AFTER_REACH);
        for (const [pos, token] of found) {
          const person = this.persons.get(token)!;
          if (role && pos >= start && pos < m.index! && person.role === null) person.role = role;
        }
      }
      boundary = m.index! + m[0].length;
    }
  }

  private knownPerson(first: string, last: string): string | undefined {
    const [f, l] = [parts(first), parts(last)];
    const t1 = f.length ? this.wordToken(f[0]) : undefined;
    const t2 = l.length ? this.wordToken(l[0]) : undefined;
    return t1 && t1 === t2 ? t1 : undefined;
  }

  private wordToken(word: string): string | undefined {
    return this.personStems.get(stem(word)) ?? this.tokenByBase(word);
  }

  private notePerson(token: string, name: string, role: string | null, address: string | null) {
    const entry = this.persons.get(token) ?? { name, role: null, address: null };
    entry.role = entry.role ?? role;
    entry.address = entry.address ?? address;
    this.persons.set(token, entry);
  }

  private registerPerson(first: string, last: string, middle: string | null = null): string {
    const key = this.key("OSOBA", `${first} ${last}`);
    const knownFirst = this.wordToken(parts(first)[0]);
    const knownLast = this.wordToken(parts(last)[0]);
    if (!this.byOriginal.has(key) && knownFirst && knownFirst === knownLast) this.byOriginal.set(key, knownFirst);
    if (!this.byOriginal.has(key)) {
      const n = (this.counters.get("OSOBA") ?? 0) + 1;
      this.counters.set("OSOBA", n);
      const token = `[OSOBA_${n}]`;
      this.byOriginal.set(key, token);
      this.mapping.set(token, middle ? `${first} ${middle} ${last}` : `${first} ${last}`);
    }
    const token = this.byOriginal.get(key)!;
    for (const word of [first, last, middle].filter((n): n is string => !!n).flatMap(parts)) {
      const s = stem(word);
      if (!this.personStems.has(s)) this.personStems.set(s, token);
      const base = word.toLowerCase().replace(/[aeiouyąę]+$/u, "");
      // Fleeting "e" in Polish inflection: Paweł -> Pawła/Pawłowi, Marek -> Marka, Jacek -> Jacka.
      const fleeting = base.replace(/e(?=[a-ząćęłńóśźż]$)/u, "");
      for (const variant of new Set([base, fleeting])) {
        if ([...variant].length >= 4 && !this.personBases.has(variant)) this.personBases.set(variant, token);
      }
    }
    return token;
  }

  anonymize(text: string): string {
    for (const rule of RULES) text = this.applyRule(text, rule);
    text = text.replace(ADDRESS, (m) => this.token("ADRES", m));
    return this.replacePersonWords(text);
  }

  private applyRule(text: string, rule: Rule): string {
    const group = rule.group ?? 0;
    const re = new RegExp(rule.pattern.source, rule.pattern.flags.includes("d") ? rule.pattern.flags : rule.pattern.flags + "d");
    let out = "";
    let pos = 0;
    for (const m of text.matchAll(re)) {
      const value = m[group];
      if (value === undefined || value.startsWith("[") || (rule.check && !rule.check(value))) continue;
      const token = this.token(rule.label, value);
      const [start, end] = m.indices![group]!;
      out += text.slice(pos, start) + token;
      pos = end;
    }
    return out + text.slice(pos);
  }

  private tokenByBase(word: string): string | undefined {
    const lowered = word.toLowerCase();
    for (const [base, token] of this.personBases) {
      if (lowered.startsWith(base) && [...lowered].length - [...base].length <= 4) return token;
    }
    return undefined;
  }

  private formToken(token: string, form: string): string {
    if (this.mapping.get(token) === form) return token;
    const key = this.key("FORM", `${token}|${form}`);
    if (!this.byOriginal.has(key)) {
      const prefix = token.slice(0, -1) + ".";
      const k = [...this.mapping.keys()].filter((t) => t.startsWith(prefix)).length + 1;
      const sub = `${token.slice(0, -1)}.${k}]`;
      this.byOriginal.set(key, sub);
      this.mapping.set(sub, form);
    }
    return this.byOriginal.get(key)!;
  }

  private replacePersonWords(text: string): string {
    if (!this.personStems.size) return text;
    // Full "First Last" pairs first (scanned word by word, overlapping).
    const words = [...text.matchAll(PERSON_WORD)];
    let out = "";
    let pos = 0;
    let i = 0;
    while (i < words.length - 1) {
      const a = words[i];
      let b = words[i + 1];
      const aEnd = a.index! + a[0].length;
      const gap = text.slice(aEnd, b.index!);
      if (gap.trim() === "" && !gap.includes("\n\n")) {
        const t1 = this.wordToken(a[0]);
        const t2 = this.wordToken(b[0]);
        if (t1 && t1 === t2) {
          // extend to a following word of the same person ("Adam Michał Nowak")
          while (i + 2 < words.length) {
            const c = words[i + 2];
            const gapC = text.slice(b.index! + b[0].length, c.index!);
            const tc = this.wordToken(c[0]);
            if (gapC.trim() !== "" || gapC.includes("\n\n") || tc !== t1) break;
            b = c;
            i += 1;
          }
          const form = text.slice(a.index!, b.index! + b[0].length);
          const token = this.formToken(t1, form);
          this.replacements.push({ token, original: form, label: "OSOBA" });
          out += text.slice(pos, a.index!) + token;
          pos = b.index! + b[0].length;
          i += 2;
          continue;
        }
      }
      i += 1;
    }
    text = out + text.slice(pos);
    return text.replace(PERSON_WORD, (word) => {
      const token = this.wordToken(word);
      if (token && !STOP.has(word)) {
        const t = this.formToken(token, word);
        this.replacements.push({ token: t, original: word, label: "OSOBA" });
        return t;
      }
      return word;
    });
  }
}

export function restore(text: string, mapping: Map<string, string>): string {
  return text.replace(/\[[A-Z]+_\d+(?:\.\d+)?\]/g, (t) => mapping.get(t) ?? t);
}

export function anonymizePages(documents: Map<string, string[]>) {
  const anon = new Anonymizer();
  anon.learnNames([...documents.values()].flat());
  const out = new Map([...documents].map(([id, pages]) => [id, pages.map((p) => anon.anonymize(p))]));
  const persons: Person[] = [...anon.persons].map(([token, p]) => ({ token, ...p }));
  return { pages: out, anonymizer: anon, persons };
}

export function findLeaks(text: string, known: Iterable<string>): string[] {
  const norm = text.replace(/\s+/g, " ");
  return [...known].filter((v) => v && norm.includes(v.replace(/\s+/g, " ")));
}

// --- review aid (browser only, not part of the Python parity) ---------------------------------

// Capitalized words that are common in a komparycja and are not names.
const NOT_NAMES = new Set(["Kancelarii", "Kancelaria", "Notarialnej", "Notarialna", "Notariuszem", "Notariusza", "Sąd", "Sądzie",
  "Rejonowy", "Wydział", "Wydziale", "Ksiąg", "Wieczystych", "Rejestru", "Sądowego", "Przedsiębiorców", "Ministerstwa",
  "Sprawiedliwości", "Zarządu", "Członek", "Prezes", "Prokurent", "Akt", "Akcie", "Umowa", "Umowy", "Dnia", "Repertorium",
  "Stawający", "Stawająca", "Stawającej", "Stawających", "Tożsamość", "Gospodarczy", "Polsce", "Polski", "Polska",
  "Ograniczoną", "Odpowiedzialnością", "Europejskiego", "Obszaru", "Gospodarczego"]);
const SUSPECT = new RegExp(`${B_START}(?:${WORD}|[A-ZŁŚŻŹĆŃÓĘĄ]{3,})(?:[ \t]+(?:${WORD}|[A-ZŁŚŻŹĆŃÓĘĄ]{3,})){1,2}${B_END}`, "gu");

/** Pairs of capitalized words left in the anonymized komparycja: possibly names the rules missed.
 *  Only a hint for the lawyer's review — it never changes the text. */
export function suspiciousWords(anonymizedPages: string[]): string[] {
  const text = anonymizedPages.join("\n");
  const [start, stop] = komparycja(text);
  const region = start === stop ? text.slice(0, 3000) : text.slice(start, stop);
  const out = new Set<string>();
  for (const m of region.matchAll(SUSPECT)) {
    const words = m[0].split(/[ \t]+/u);
    if (words.some((w) => isTerm(w) || NOT_NAMES.has(w))) continue;
    if (words.every((w) => w === w.toUpperCase()) && words.length < 2) continue;
    out.add(m[0]);
  }
  return [...out];
}
